// Node: "Guard 1: Size sanity"
// Place: AFTER all ffmpegCommandExecute nodes (they all converge here).
// Output 1 â†’ Pass (continue to duration check)
// Output 2 â†’ Fail (dead-end, source NOT replaced)
// Purpose: Reject encodes that didn't shrink the file meaningfully, OR
//          produced suspiciously small output (likely corrupt).

module.exports = async (args) => {
  const snap = (args.variables && args.variables.user) || {};
  const inputBytes = snap.sourceSize;
  const outputBytes = args.inputFileObj.file_size;

  if (!inputBytes) {
    args.jobLog('Size check: no source snapshot found â€” FAIL (will not replace)');
    return {
      outputFileObj: args.inputFileObj,
      outputNumber: 2,
      variables: args.variables,
    };
  }

  const ratio = outputBytes / inputBytes;
  args.jobLog(
    `Size check: ${(inputBytes / 1024).toFixed(2)}GiB â†’ ` +
      `${(outputBytes / 1024).toFixed(2)}GiB (${(ratio * 100).toFixed(1)}%)`,
  );

  if (outputBytes < inputBytes * 0.05) {
    args.jobLog('Size check: FAIL â€” output suspiciously small (<5% of source), likely corrupt');
    return {
      outputFileObj: args.inputFileObj,
      outputNumber: 2,
      variables: args.variables,
    };
  }

  if (ratio >= 0.95) {
    args.jobLog('Size check: FAIL â€” output not meaningfully smaller (>=95% of source)');
    return {
      outputFileObj: args.inputFileObj,
      outputNumber: 2,
      variables: args.variables,
    };
  }

  return {
    outputFileObj: args.inputFileObj,
    outputNumber: 1,
    variables: args.variables,
  };
};

// Node: "Guard 2: Duration integrity"
// Place: AFTER size check.
// Output 1 â†’ Pass
// Output 2 â†’ Fail (truncated or corrupt output)
// Purpose: Catches encodes that crashed mid-way and produced a truncated file.
//          Allows up to 0.5% duration drift (rounding/container differences).

module.exports = async (args) => {
  const snap = (args.variables && args.variables.user) || {};
  const inDur = snap.sourceDuration;

  const fmt = (args.inputFileObj.ffProbeData || {}).format || {};
  const outDur = parseFloat(fmt.duration || 0);

  if (!inDur) {
    args.jobLog('Duration check: no source snapshot â€” PASS (skipping)');
    return {
      outputFileObj: args.inputFileObj,
      outputNumber: 1,
      variables: args.variables,
    };
  }

  if (!outDur) {
    args.jobLog('Duration check: cannot read output duration â€” FAIL');
    return {
      outputFileObj: args.inputFileObj,
      outputNumber: 2,
      variables: args.variables,
    };
  }

  const ratio = outDur / inDur;
  args.jobLog(
    `Duration check: ${inDur.toFixed(1)}s â†’ ${outDur.toFixed(1)}s (${(ratio * 100).toFixed(2)}%)`,
  );

  if (ratio < 0.995 || ratio > 1.005) {
    args.jobLog('Duration check: FAIL â€” duration drift > 0.5%');
    return {
      outputFileObj: args.inputFileObj,
      outputNumber: 2,
      variables: args.variables,
    };
  }

  return {
    outputFileObj: args.inputFileObj,
    outputNumber: 1,
    variables: args.variables,
  };
};

// Node: "Guard 3: HDR metadata survived"
// Place: AFTER duration check, BEFORE rename.
// Output 1 â†’ Pass (continue to rename â†’ replace)
// Output 2 â†’ Fail (HDR side data was lost in encode, source NOT replaced)
// Purpose: Ensures mastering display + content light level survived the QSV pipeline.
//          SDR sources pass through automatically (no HDR to check).

module.exports = async (args) => {
  const snap = (args.variables && args.variables.user) || {};

  if (!snap.sourceWasHDR) {
    args.jobLog('HDR survival: source was SDR â€” PASS (no HDR check needed)');
    return {
      outputFileObj: args.inputFileObj,
      outputNumber: 1,
      variables: args.variables,
    };
  }

  // First check stream-level side data (fast, already in ffProbeData)
  const streams = (args.inputFileObj.ffProbeData || {}).streams || [];
  const videoStream = streams.find((s) => s.codec_type === 'video') || {};
  const streamSd = videoStream.side_data_list || [];

  let hasMaster = streamSd.some((x) =>
    (x.side_data_type || '').toLowerCase().includes('mastering'),
  );
  let hasCLL = streamSd.some((x) =>
    (x.side_data_type || '').toLowerCase().includes('content light'),
  );

  // Fall back to frame-level probe if stream-level didn't have it
  if (!hasMaster || !hasCLL) {
    try {
      const { execSync } = require('child_process');
      const out = execSync(
        `ffprobe -v error -select_streams v:0 -read_intervals "%+#1" ` +
          `-show_frames -show_entries frame=side_data_list -of json ` +
          `"${args.inputFileObj._id}"`,
        { maxBuffer: 10 * 1024 * 1024 },
      ).toString();
      const frameSd = ((JSON.parse(out).frames || [])[0] || {}).side_data_list || [];
      hasMaster =
        hasMaster ||
        frameSd.some((x) => (x.side_data_type || '').toLowerCase().includes('mastering'));
      hasCLL =
        hasCLL ||
        frameSd.some((x) => (x.side_data_type || '').toLowerCase().includes('content light'));
    } catch (e) {
      args.jobLog(`HDR survival: frame-level ffprobe failed (${e.message})`);
    }
  }

  args.jobLog(`HDR survival: mastering=${hasMaster} cll=${hasCLL}`);

  if (!hasMaster || !hasCLL) {
    args.jobLog('HDR survival: FAIL â€” HDR side data missing from output');
    return {
      outputFileObj: args.inputFileObj,
      outputNumber: 2,
      variables: args.variables,
    };
  }

  return {
    outputFileObj: args.inputFileObj,
    outputNumber: 1,
    variables: args.variables,
  };
};

// Node: "AV1 tuning (encoder-aware) - cq28 SDR"
// Replaces ffmpegCommandCustomArguments, which appended QSV-only options
// unconditionally. On a CPU job the encoder is libsvtav1, which rejects
// "-preset medium" and has no -global_quality / -look_ahead, so ffmpeg died at
// encoder init and every CPU transcode failed (88/88 since 2026-08-29).
//
// Emits tuning matched to the encoder the preceding SetVideoEncoder node
// actually chose. Fails CLOSED: an unrecognised encoder dead-ends (output 2,
// which has no edge) rather than shipping arguments it may reject.
//
// It is also the 4K CPU GUARD. Measured 2026-08-31 on this node, a 3840x2160
// `libsvtav1 -preset 8` encode peaks at ~7,100 MiB RSS against the container's
// 4Gi limit and OOM-kills the whole tdarr-tdarr-node container (exit 137),
// taking whatever the GPU worker was doing down with it. The same file on
// av1_qsv peaks at ~1,225 MiB and is faster (54 vs 43 fps). The B70 is mounted
// into this container unconditionally (devic.es/b70-vaapi), so when a CPU
// worker is about to run libsvtav1 on a frame too large to hold, this rewrites
// the already-chosen encoder to av1_qsv. Files it does not touch keep the CPU
// fallback PR #1443 added.
//
// The guard lives HERE, not in an earlier node, for two measured reasons:
//   * `args.workerType` mutated in an earlier customFunction does NOT reach
//     ffmpegCommandSetVideoEncoder - each node is handed its own worker
//     context, so flipping it upstream is silently ignored (observed
//     2026-08-31: guard logged the flip, ffmpeg still ran `-c:0 libsvtav1`).
//   * The community `tagsRequeue` node cannot be used to hand the file to a
//     GPU worker instead. It does set the staged status to
//     `queued:requireGPU` (observed), but when the flow then ends the job is
//     finalised "Not required", the staged row is deleted and the file leaves
//     the queue permanently. Measured three times, once in isolation with
//     health checks suppressed. The require* routing in getStagedFiles is not
//     Pro-gated (unlike nodeTags) - it is the flow-end finalisation that
//     discards it.
// It decides on the video's own PIXEL COUNT converted to a measured memory
// need, never on filename, library or path, so 4K arriving by ANY route is
// covered.

// VA-API PROBE. Whenever the encoder that will actually run is av1_qsv (a GPU
// job, or a 4K job rewritten from libsvtav1 above), open the VA-API device
// first. A dead B70 path (late-trained dock, renamed DRM node) otherwise only
// shows at ffmpeg init, "Failed to create a VAAPI device", exit 187, and the
// queue chews through every movie in ~25 s each (35 on 2026-10-06). The probe
// throws instead of returning an edge: a dead-end output finalises the job
// "Not required" and drops the file from the queue, while a throw leaves a
// retryable transcode error with a distinct "VA-API probe FAILED" report line.
// libsvtav1 jobs never reach it, so the CPU worker keeps working.
const VAAPI_DEVICE = '/dev/dri/renderD129';

function probeVaapi() {
  const { execFileSync } = require('child_process');
  try {
    const out = execFileSync('vainfo', ['--display', 'drm', '--device', VAAPI_DEVICE], {
      timeout: 15000,
      stdio: ['ignore', 'pipe', 'pipe'],
    }).toString();
    if (/AV1Profile0\s*:\s*VAEntrypointEncSlice/.test(out)) return { ok: true, detail: 'AV1 EncSlice present' };
    return { ok: false, detail: 'vainfo ran but lists no AV1 encode entrypoint' };
  } catch (e) {
    const msg = String((e && (e.stderr || e.message)) || e).trim().split('\n')[0];
    return { ok: false, detail: msg };
  }
}

module.exports = async (args) => {
  const QUALITY = 28;   // av1_qsv -global_quality, libsvtav1 -crf
  const SVT_PRESET = '8';        // libsvtav1 -preset, 0-13, lower = slower/better.
                                 // 8, not 6: this is the FALLBACK worker, so keep
                                 // throughput up during a GPU outage. Tunable.
  const HDR = false;           // emit HDR10 signalling tags

  const cmd = args.variables && args.variables.ffmpegCommand;
  if (!cmd || !Array.isArray(cmd.overallOuputArguments)) {
    args.jobLog('AV1 tuning: ffmpegCommand not initialised - FAIL (will not encode)');
    return { outputFileObj: args.inputFileObj, outputNumber: 2, variables: args.variables };
  }

  // Read back the encoder chosen upstream: SetVideoEncoder pushes
  // ['-c:{outputIndex}', <encoder>] onto the video stream's outputArgs.
  let encoder = '';
  const streams = cmd.streams || [];
  for (let i = 0; i < streams.length && !encoder; i += 1) {
    const s = streams[i];
    if (s.codec_type !== 'video' || s.codec_name === 'mjpeg') continue;
    const oa = s.outputArgs || [];
    for (let j = 0; j < oa.length - 1; j += 1) {
      if (String(oa[j]).indexOf('-c:') === 0) { encoder = String(oa[j + 1]); break; }
    }
  }

  // --- 4K CPU guard: keep libsvtav1 away from frames it cannot hold ---
  // Calibration measured 2026-08-31 on tdarr-tdarr-node (talos-3):
  //   3840x2160 = 8.2944 Mpx -> ~7100 MiB RSS for libsvtav1 -preset 8
  const MIB_PER_MEGAPIXEL = 856;      // 7100 / 8.2944
  const CPU_FFMPEG_BUDGET_MIB = 2800; // 4096 MiB limit, minus node + healthcheck
  if (encoder === 'libsvtav1') {
    // Dimensions come from the streams this command will actually encode, the
    // same list the encoder rewrite below walks - not from inputFileObj, so the
    // guard and the rewrite can never disagree about which stream is the video.
    let pixels = 0;
    for (let i = 0; i < streams.length; i += 1) {
      const s = streams[i] || {};
      if (String(s.codec_type) !== 'video') continue;
      if (String(s.codec_name).toLowerCase() === 'mjpeg') continue; // cover art
      if (s.removed) continue;
      const area = Number(s.width || 0) * Number(s.height || 0);
      if (area > pixels) pixels = area;
    }
    const estimateMiB = Math.round((pixels / 1000000) * MIB_PER_MEGAPIXEL);
    // Unknown dimensions are treated as too big: failing towards the GPU costs
    // throughput, failing towards libsvtav1 costs the whole node.
    if (pixels === 0 || estimateMiB > CPU_FFMPEG_BUDGET_MIB) {
      for (let i = 0; i < streams.length; i += 1) {
        const st = streams[i];
        if (st.codec_type !== 'video' || st.codec_name === 'mjpeg') continue;
        const oa = st.outputArgs || [];
        for (let j = 0; j < oa.length - 1; j += 1) {
          if (String(oa[j]).indexOf('-c:') === 0 && String(oa[j + 1]) === 'libsvtav1') {
            oa[j + 1] = 'av1_qsv';
          }
        }
      }
      args.jobLog('AV1 tuning: 4K CPU guard - pixels=' + pixels +
                  ' estCpuRss=' + (pixels === 0 ? 'unknown' : estimateMiB + 'MiB') +
                  ' budget=' + CPU_FFMPEG_BUDGET_MIB +
                  'MiB -> libsvtav1 would OOM this container, encoding av1_qsv instead');
      encoder = 'av1_qsv';
    }
  }

  if (encoder === 'av1_qsv') {
    const probe = probeVaapi();
    if (!probe.ok) {
      const msg = 'VA-API probe FAILED on ' + VAAPI_DEVICE + ': ' + probe.detail +
                  ' - not encoding; GPU path is dead, see skill intel-gpu vaapi-check.md';
      args.jobLog(msg);
      throw new Error(msg);
    }
    args.jobLog('VA-API probe: ok (' + VAAPI_DEVICE + ', ' + probe.detail + ')');
  }

  const out = [];
  if (HDR) {
    out.push('-color_primaries', 'bt2020', '-color_trc', 'smpte2084',
             '-colorspace', 'bt2020nc', '-color_range', 'tv');
  }

  if (encoder === 'av1_qsv') {
    out.push('-preset', 'medium', '-global_quality', String(QUALITY), '-look_ahead', '1');
  } else if (encoder === 'libsvtav1') {
    out.push('-preset', SVT_PRESET, '-crf', String(QUALITY));
  } else {
    args.jobLog('AV1 tuning: unrecognised encoder "' + encoder + '" - FAIL (will not encode)');
    return { outputFileObj: args.inputFileObj, outputNumber: 2, variables: args.variables };
  }

  cmd.overallOuputArguments.push.apply(cmd.overallOuputArguments, out);
  args.jobLog('AV1 tuning: encoder="' + encoder + '" quality=' + QUALITY +
              ' hdr=' + HDR + ' args=[' + out.join(' ') + ']');

  return { outputFileObj: args.inputFileObj, outputNumber: 1, variables: args.variables };
};

// Node: "Conform streams for matroska (convert, do not drop)"
// Place: AFTER Set Container mkv, BEFORE Set Video Encoder.
// Output 1 -> continue
// Output 2 -> FAIL (dead end, nothing encoded)
//
// Why this exists: matroska cannot mux mov_text, and Tdarr's own
// `forceConform` option DELETES those streams (1-46 subtitle tracks on the
// parked 4K masters). This converts them to subrip instead, so every track
// survives, and drops only the streams matroska genuinely cannot carry and
// which have no text equivalent.

module.exports = async (args) => {
  const cmd = args.variables && args.variables.ffmpegCommand;
  if (!cmd || !Array.isArray(cmd.streams)) {
    args.jobLog('Stream conform: ffmpegCommand not initialised - FAIL (will not encode)');
    return { outputFileObj: args.inputFileObj, outputNumber: 2, variables: args.variables };
  }

  const UNMUXABLE = ['bin_data', 'timed_id3', 'eia_608'];
  const before = { video: 0, audio: 0, subtitle: 0, other: 0 };
  let convertedSubs = 0;
  let droppedData = 0;
  let droppedArt = 0;

  for (let i = 0; i < cmd.streams.length; i += 1) {
    const s = cmd.streams[i];
    if (s.removed) continue;
    const type = String(s.codec_type || '');
    const name = String(s.codec_name || '').toLowerCase();
    if (before[type] === undefined) before.other += 1; else before[type] += 1;

    // matroska has no mov_text mapping. Convert to subrip, never delete.
    if (type === 'subtitle' && name === 'mov_text') {
      s.outputArgs.push('-c:{outputIndex}', 'srt');
      convertedSubs += 1;
      continue;
    }

    // No text equivalent and matroska cannot carry them.
    if (type === 'data' || UNMUXABLE.indexOf(name) !== -1) {
      s.removed = true;
      droppedData += 1;
      continue;
    }

    // Cover art with no dimensions -> matroska "dimensions not set".
    // Drop only the broken art stream; valid art (e.g. 600x900) is kept.
    // ffmpegCommandStart rewrites attached_pic streams to codec_type
    // 'attachment', so cover art arrives as 'attachment', not 'video'
    // (Amelie: eight 0x0 mjpeg counted as other=8, none dropped).
    if ((type === 'video' || type === 'attachment') && name === 'mjpeg') {
      const w = Number(s.width || 0);
      const h = Number(s.height || 0);
      if (!w || !h) {
        s.removed = true;
        droppedArt += 1;
        continue;
      }
    }
  }

  args.jobLog(
    'Stream conform: in v=' + before.video + ' a=' + before.audio +
      ' s=' + before.subtitle + ' other=' + before.other +
      ' | mov_text->srt=' + convertedSubs +
      ' droppedData=' + droppedData + ' dropped0x0Art=' + droppedArt,
  );

  return { outputFileObj: args.inputFileObj, outputNumber: 1, variables: args.variables };
};

