    user.expectVideo = count('video');
    user.expectSubtitle = count('subtitle');
    return { outputFileObj: args.inputFileObj, outputNumber: 2, variables: args.variables };
  }

  let dropped = 0;
  for (const s of audio) {
    if (keep.indexOf(s) === -1) {
      s.removed = true;
      dropped += 1;
    }
